def transform(grid):
    """Fill 2 between horizontal neighbors with equal non-zero values."""
    result = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if c == 0 or c == len(grid[r]) - 1:
                continue
            val = grid[r][c]
            left = result[r][c-1]  # already transformed
            right = grid[r][c+1]   # original
            if left == right and left != 0 and left != val:
                result[r][c] = 2
